import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Timeline","description":"Display entries across two linked Grids on a timeline.","frontmatter":{"title":"Timeline","description":"Display entries across two linked Grids on a timeline."},"headers":[],"relativePath":"en/ansichten/timeline.md","filePath":"en/ansichten/timeline.md","lastUpdated":1787319236000}'),r={name:"en/ansichten/timeline.md"};function o(s,e,d,l,h,p){return i(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h1><p>The <strong>Timeline</strong> shows entries on a timeline — with a start and end date, grouped into rows.</p><p><strong>Suited for:</strong> project planning, booking schedules, resource overviews, staff scheduling.</p><div class="warning custom-block"><p class="custom-block-title">Plan-dependent</p><p>The Timeline isn&#39;t available on all plans. The upgrade notice reads <em>Upgrade to Pro to add Timeline views.</em></p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>The Timeline is the <strong>only view configured across two Grids</strong>. That makes it more powerful, but also more involved to set up than any other view.</p><div class="tip custom-block"><p class="custom-block-title">The design is intentional</p><p>A timeline needs <strong>rows</strong> and <strong>bars</strong> — and those are two different things: rooms and bookings, staff and assignments, machines and orders. A single Grid couldn&#39;t express that.</p><p>So plan your data model with two Grids from the start if you need a Timeline.</p></div><div class="warning custom-block"><p class="custom-block-title">Two conditions must be met</p><p><strong>1. A field of type <em>Link multiple records</em></strong> in the Grid the view sits on.</p><blockquote><p><em>To see a Timeline, your Grid needs a column of type multiple link.</em></p></blockquote><p><strong>2. Date fields in the linked Grid</strong> — that&#39;s where start and end live.</p><blockquote><p><em>The referenced Grid has no date or date-time fields.</em></p></blockquote></div><div class="tip custom-block"><p class="custom-block-title">Where &quot;multiple link&quot; comes from</p><p>The message uses the term <em>multiple link</em>. That refers to the column type otherwise called <strong>Link multiple records</strong> everywhere else. → <a href="/en/grids/verknuepfungen">Linking Grids</a></p></div><h2 id="the-structure" tabindex="-1">The structure <a class="header-anchor" href="#the-structure" aria-label="Permalink to &quot;The structure&quot;">​</a></h2><p>An example for a booking schedule:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Grid &quot;Rooms&quot;                    Grid &quot;Bookings&quot;</span></span>
<span class="line"><span>├── Name                        ├── Title</span></span>
<span class="line"><span>└── Bookings   ←─────────────────┤ Room</span></span>
<span class="line"><span>    (Link multiple                ├── From   (Date)</span></span>
<span class="line"><span>     records)                     └── To     (Date)</span></span></code></pre></div><p>The Timeline sits on <strong>&quot;Rooms&quot;</strong>:</p><ul><li>Each room becomes a <strong>row</strong> of the timeline.</li><li>The linked <strong>Bookings</strong> appear as bars within it.</li><li>Their start and end date determine position and length.</li></ul><div class="tip custom-block"><p class="custom-block-title">The mental model</p><p>The Grid the Timeline sits on provides the <strong>rows</strong>, the linked Grid provides the <strong>bars</strong>.</p><p>So build your data model from this question: <em>What should be stacked, row by row?</em> Rooms, staff, machines, projects — that&#39;s the Grid the view sits on.</p></div><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><ol><li>Create both Grids and link them via <strong>Link multiple records</strong>.</li><li>Make sure the linked Grid has date fields for start and end.</li><li>Under the first Grid, choose <strong>Create view</strong> → <strong>Timeline</strong>.</li><li>Open <strong>Timeline</strong> and configure:</li></ol><p>The dialog is called <em>Configure Timeline</em>:</p><blockquote><p><em>Choose a reference field and date fields to create the Timeline.</em></p></blockquote><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Reference field</strong></td><td>The link column the bars come from</td></tr><tr><td><strong>Start date</strong></td><td>Date field in the linked Grid</td></tr><tr><td><strong>End date</strong></td><td>Date field in the linked Grid</td></tr></tbody></table><p>Save with <strong>Save</strong>. If the link is missing, ApptiveGrid offers <strong>Add reference field</strong>.</p><h2 id="working-in-the-timeline" tabindex="-1">Working in the timeline <a class="header-anchor" href="#working-in-the-timeline" aria-label="Permalink to &quot;Working in the timeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th></th></tr></thead><tbody><tr><td><strong>Time grid</strong></td><td><em>Day</em>, <em>Week</em>, <em>Month</em>, <em>Year</em></td></tr><tr><td><strong>Today</strong></td><td>Jumps to the current date</td></tr><tr><td><strong>Row</strong></td><td>Header of the row column</td></tr></tbody></table><p>Entries without a title appear as <strong>Untitled</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Which grid for which planning horizon</p><ul><li><strong>Day</strong> for day-level planning with times</li><li><strong>Week</strong> for operational scheduling</li><li><strong>Month</strong> for project phases</li><li><strong>Year</strong> for annual planning and utilization</li></ul><p>The year grid has no equivalent in any other view — for that, the Timeline is the only tool.</p></div><h2 id="timeline-or-calendar" tabindex="-1">Timeline or Calendar? <a class="header-anchor" href="#timeline-or-calendar" aria-label="Permalink to &quot;Timeline or Calendar?&quot;">​</a></h2><p>Both display time, but solve different problems:</p><table tabindex="0"><thead><tr><th></th><th><a href="/en/ansichten/kalender">Calendar</a></th><th>Timeline</th></tr></thead><tbody><tr><td>Basis</td><td>one date field in the same Grid</td><td>a link plus two date fields in the target Grid</td></tr><tr><td>Structure</td><td>one Grid</td><td><strong>two Grids</strong></td></tr><tr><td>Display</td><td>calendar sheet</td><td>timeline with rows</td></tr><tr><td>Grid</td><td>Day, Week, Month</td><td>Day, Week, Month, <strong>Year</strong></td></tr><tr><td>Strength</td><td>appointments</td><td><strong>utilization and overlaps</strong></td></tr><tr><td>Plan</td><td>all plans</td><td>plan-dependent</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">When the extra effort pays off</p><p>If you just want to see appointments, use the Calendar — it&#39;s set up in a minute.</p><p>The Timeline pays off when you want to compare <strong>overlapping bookings</strong>: which room is free? Which machine is overbooked? Who has capacity when? That&#39;s exactly what a calendar doesn&#39;t show.</p></div><h2 id="when-nothing-appears" tabindex="-1">When nothing appears <a class="header-anchor" href="#when-nothing-appears" aria-label="Permalink to &quot;When nothing appears&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td><em>To see a Timeline, your Grid needs a column of type multiple link.</em></td><td>No column of type <em>Link multiple records</em> exists</td></tr><tr><td><em>The referenced Grid has no date or date-time fields.</em></td><td>Date fields are missing in the target Grid</td></tr><tr><td>Rows without bars</td><td>The entries have no link, or their date fields are empty</td></tr><tr><td>Bars in the wrong place</td><td>Start and end date swapped</td></tr><tr><td>Can&#39;t create the view</td><td>Check your plan</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Finding data gaps</p><p>A filter <code>From</code> <em>is empty</em> in the linked Grid shows all entries that can&#39;t appear on the Timeline. → <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li><li><a href="/en/ansichten/kalender">Calendar</a></li><li><a href="/en/grids/verknuepfungen">Linking Grids</a></li></ul>`,34)])])}const u=t(r,[["render",o]]);export{c as __pageData,u as default};
